(* [comment removed for export] *)
Lemma strip_walk : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz : Z) (ws : list word),
  u32arr rsegs m B ws -> (0 <= ia <= iz)%Z -> (iz <= Z.of_nat (length ws))%Z -> (iz - ia <= Z.of_nat n)%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  limbs_ok ws ia iz ->
  s1 = Z_to_bv 64 (B + 4 * ia) -> s7 = Z_to_bv 64 (B + 4 * iz) ->
  evt rsegs (fun ms' => exists (iz' : Z) a2' s7',
      (ia <= iz' <= iz)%Z /\ (forall k w, (iz' <= k < iz)%Z -> nth_error ws (Z.to_nat k) = Some w -> bv_unsigned w = 0%Z) /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7' s8 s9 s10 (Z_to_bv 64 (B + 4 * iz')) t3 t4 t5 t6) F
               (Z_to_bv 64 0xb0774) fc None m (seg_rom rsegs))
