Definition e2pos_post (ra sp gp tp t0 t1 t2 s0 a0 a1 a6 a7 s2 s4 s5 s6 s8 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (B ia iz0 : Z) (L : nat) : machine_state -> Prop :=
  fun ms' => exists (ia' iz' : Z) a2' a3' a4' a5' m' ws',
    (1 <= ia' < iz' /\ ia' <= ia)%Z /\ (iz' <= iz0)%Z /\
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia')) a0 a1 a2' a3' a4' a5' a6 a7
                  s2 (Z_to_bv 64 0) s4 s5 s6 (Z_to_bv 64 (B + 4 * iz')) s8 s9 s10 (Z_to_bv 64 (B + 4 * iz')) t3 t4 t5 t6) F
             (Z_to_bv 64 0xb0824) fc None m' (seg_rom rsegs)
    /\ munch [(B, B + 4 * iz0); (bv_unsigned s0 + -424, bv_unsigned s0 + -420)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ u32arr rsegs m' B ws' /\ length ws' = L /\ limbs_ok ws' ia' iz0
    /\ (exists w', nth_error ws' (Z.to_nat ia') = Some w' /\ bv_unsigned w' <> 0%Z)
    /\ rw_cells rsegs m' (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 0)].

(* [comment removed for export] *)
Lemma e2pos_body : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz iz0 e2 sh : Z) (ws : list word) (w0 : word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (1 <= ia < iz)%Z -> (iz <= iz0 <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  limbs_ok ws ia iz0 -> nth_error ws (Z.to_nat ia) = Some w0 -> bv_unsigned w0 <> 0%Z -> (1 <= sh <= 29)%Z -> (sh <= e2 < 2 ^ 31)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 e2)] -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 424)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z ->
  a0 = Z_to_bv 64 MAGIC9 -> a1 = Z_to_bv 64 1000000000 -> s1 = Z_to_bv 64 (B + 4 * ia) -> s3 = Z_to_bv 64 sh -> s7 = Z_to_bv 64 (B + 4 * iz) ->
  evt rsegs (fun ms' => exists (ia' iz' : Z) a2' a3' a4' a5' m' ws',
      (ia - 1 <= ia' <= ia)%Z /\ (ia' < iz' <= iz)%Z /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia')) a0 a1 a2' a3' a4' a5' a6 a7
                    s2 (Z_to_bv 64 (e2 - sh)) s4 s5 s6 (Z_to_bv 64 (B + 4 * iz')) s8 s9 s10 (Z_to_bv 64 (B + 4 * iz')) t3 t4 t5 t6) F
               (Z_to_bv 64 (if (e2 - sh =? 0)%Z then 0xb0824 else 0xb0788)) fc None m' (seg_rom rsegs)
      /\ munch [(B, B + 4 * iz0); (bv_unsigned s0 + -424, bv_unsigned s0 + -420)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' B ws' /\ length ws' = length ws /\ limbs_ok ws' ia' iz0
      /\ (exists w', nth_error ws' (Z.to_nat ia') = Some w' /\ bv_unsigned w' <> 0%Z)
      /\ rw_cells rsegs m' (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 (e2 - sh))])
