(* [comment removed for export] *)
Definition limbs_nz (ws : list word) (lo hi : Z) : Prop :=
  exists i w, (lo <= i < hi)%Z /\ nth_error ws (Z.to_nat i) = Some w /\ bv_unsigned w <> 0%Z.

(* [comment removed for export] *)
Definition lowz (ws : list word) (ia : Z) : Prop :=
  forall i w, (0 <= i < ia)%Z -> nth_error ws (Z.to_nat i) = Some w -> bv_unsigned w = 0%Z.
Lemma lowz_upd ws ia k v : lowz ws ia -> (ia <= k)%Z -> lowz (upd ws (Z.to_nat k) v) ia.
