Definition passC_post (ra sp gp tp t2 s0 s1 a0 a1 a2 a3 a4 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (ws : list word) (B ia iz sh c : Z) : machine_state -> Prop :=
  fun ms' => exists (c' rm v : Z) m' ws',
    ms' = MS (mkR ra sp gp tp t0 (Z_to_bv 64 (B + 4 * iz)) (Z_to_bv 64 v) s0 s1 a0 a1 a2 a3 a4 a5 (Z_to_bv 64 c') a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 rm) t4 t5 t6) F (Z_to_bv 64 0xb09a8) fc None m' (seg_rom rsegs)
    /\ munch [(B + 4 * ia, B + 4 * iz)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ u32arr rsegs m' B ws' /\ length ws' = length ws /\ limbs_ok ws' ia iz
    /\ (forall i, (i < ia \/ iz <= i)%Z -> (0 <= i)%Z -> nth_error ws' (Z.to_nat i) = nth_error ws (Z.to_nat i))
    /\ (0 <= rm < 2 ^ sh)%Z /\ c' = (rm * (1000000000 / 2 ^ sh))%Z
    /\ (limbs_nz ws ia iz \/ c <> 0%Z -> limbs_nz ws' ia iz \/ c' <> 0%Z)
    /\ (exists w0, nth_error ws (Z.to_nat ia) = Some w0 /\ nth_error ws' (Z.to_nat ia) = Some (Z_to_bv 64 (bv_unsigned w0 / 2 ^ sh + c))
         /\ (ia + 1 < iz -> exists w1, nth_error ws' (Z.to_nat (ia + 1)) = Some w1 /\ (bv_unsigned w0 mod 2 ^ sh <> 0 -> bv_unsigned w1 <> 0))%Z
         /\ (ia + 1 = iz -> rm = bv_unsigned w0 mod 2 ^ sh)%Z).

(* [comment removed for export] *)
Lemma passC_walk : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B j iz sh c : Z) (ws : list word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (0 <= j)%Z -> (j + Z.of_nat n + 1 = iz)%Z -> (iz <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  limbs_ok ws j iz -> (1 <= sh <= 9)%Z -> (0 <= c <= (2 ^ sh - 1) * (1000000000 / 2 ^ sh))%Z ->
  a1 = Z_to_bv 64 1000000000 -> a5 = Z_to_bv 64 sh -> a6 = Z_to_bv 64 c -> a7 = Z_to_bv 64 (2 ^ sh - 1) -> t0 = Z_to_bv 64 (1000000000 / 2 ^ sh) ->
  t1 = Z_to_bv 64 (B + 4 * j) -> s11 = Z_to_bv 64 (B + 4 * iz) ->
  evt rsegs (passC_post ra sp gp tp t2 s0 s1 a0 a1 a2 a3 a4 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t4 t5 t6 F fc m ws B j iz sh c)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb0988) fc None m (seg_rom rsegs)).
Proof.
