Definition bodyC_post (ra sp gp tp t0 s0 s2 s5 s6 s7 s8 s9 s10 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (B iz need e2 sh : Z) (L : nat) (V : Z) : machine_state -> Prop :=
  fun ms' => exists (ia' iz' : Z) t0' t1' t2' a5' a6' a7' t3' m' ws' w0',
    (0 <= ia' < iz')%Z /\ (iz' <= Z.of_nat L)%Z /\ (iz' <= iz + 1)%Z /\
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (B + 4 * ia')) (Z_to_bv 64 (-1)) (Z_to_bv 64 1000000000) (Z_to_bv 64 need) (Z_to_bv 64 102) (Z_to_bv 64 (4 * need))
                  a5' a6' a7' s2 (Z_to_bv 64 (e2 + sh)) (Z_to_bv 64 103) s5 s6 s7 s8 s9 s10 (Z_to_bv 64 (B + 4 * iz')) t3' t4 t5 t6) F
             (Z_to_bv 64 (if (e2 + sh <? 0)%Z then 0xb0960 else 0xb0828)) fc None m' (seg_rom rsegs)
    /\ munch [(B, B + 4 * Z.of_nat L); (bv_unsigned s0 + -424, bv_unsigned s0 + -420)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ u32arr rsegs m' B ws' /\ length ws' = L /\ limbs_ok ws' ia' iz'
    /\ nth_error ws' (Z.to_nat ia') = Some w0' /\ bv_unsigned w0' <> 0%Z /\ (ia' = 0 -> bv_unsigned w0' <= V)%Z
    /\ rw_cells rsegs m' (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 (e2 + sh))] /\ lowz ws' ia'.

