Definition e2neg_post (ra sp gp tp s0 s2 s5 s6 s7 s8 s9 s10 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (B need : Z) (L : nat) (V : Z) : machine_state -> Prop :=
  fun ms' => exists (ia' iz' : Z) t0' t1' t2' a5' a6' a7' t3' m' ws' w0',
    (0 <= ia' < iz')%Z /\ (iz' <= Z.of_nat L)%Z /\
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (B + 4 * ia')) (Z_to_bv 64 (-1)) (Z_to_bv 64 1000000000) (Z_to_bv 64 need) (Z_to_bv 64 102) (Z_to_bv 64 (4 * need))
                  a5' a6' a7' s2 (Z_to_bv 64 0) (Z_to_bv 64 103) s5 s6 s7 s8 s9 s10 (Z_to_bv 64 (B + 4 * iz')) t3' t4 t5 t6) F
             (Z_to_bv 64 0xb0828) fc None m' (seg_rom rsegs)
    /\ munch [(B, B + 4 * Z.of_nat L); (bv_unsigned s0 + -424, bv_unsigned s0 + -420)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ u32arr rsegs m' B ws' /\ length ws' = L /\ limbs_ok ws' ia' iz'
    /\ nth_error ws' (Z.to_nat ia') = Some w0' /\ bv_unsigned w0' <> 0%Z /\ (ia' = 0 -> bv_unsigned w0' <= V)%Z
    /\ rw_cells rsegs m' (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 0)] /\ lowz ws' ia'.

(* [comment removed for export] *)
Lemma e2neg_walk : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 a5 a6 a7 s2 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz need e2 V : Z) (ws : list word) (w0 : word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (0 <= ia < iz)%Z -> (iz + (- e2 + 8) / 9 <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  limbs_ok ws ia iz -> nth_error ws (Z.to_nat ia) = Some w0 -> bv_unsigned w0 <> 0%Z -> (7 <= need <= 8)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -424) [C4 (Z_to_bv 64 e2)] -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 424)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z ->
  (-2000 < e2 < 0)%Z -> (- e2 <= Z.of_nat n)%Z -> (ia = 0 -> bv_unsigned w0 <= V)%Z -> lowz ws ia ->
  evt rsegs (e2neg_post ra sp gp tp s0 s2 s5 s6 s7 s8 s9 s10 t4 t5 t6 F fc m B need (length ws) V)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia)) (Z_to_bv 64 (-1)) (Z_to_bv 64 1000000000) (Z_to_bv 64 need) (Z_to_bv 64 102) (Z_to_bv 64 (4 * need)) a5 a6 a7
