Open Scope Z_scope.
(* [comment removed for export] *)
Definition ndigm1 (v : Z) : Z :=
  if v <? 10 then 0 else if v <? 100 then 1 else if v <? 1000 then 2 else if v <? 10000 then 3 else if v <? 100000 then 4
  else if v <? 1000000 then 5 else if v <? 10000000 then 6 else if v <? 100000000 then 7 else 8.
