(* [comment removed for export] *)
Lemma ecnt2_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia ir : Z) (ws : list word) (w : word),
  u32arr rsegs m B ws -> (0 <= ia < Z.of_nat (length ws))%Z -> (Z.of_nat (length ws) <= 128)%Z -> (0 <= ir <= 128)%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  nth_error ws (Z.to_nat ia) = Some w -> (bv_unsigned w < 1000000000)%Z ->
  evt rsegs (fun ms' => exists a0' a1' a2' a3',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia)) a0' a1' a2' a3' a4 a5 a6 a7 s2 s3 s4
                  (Z_to_bv 64 (9 * (ir - ia) + ndigm1 (bv_unsigned w))) (Z_to_bv 64 (B + 4 * ir)) s7 s8 s9 s10 s11 t3 t4 t5 t6) F
               (Z_to_bv 64 0xb10e4) fc None m (seg_rom rsegs))
