(* [comment removed for export] *)
Lemma rcarry_walk : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia k : Z) (ws : list word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (0 <= ia)%Z -> (k = ia - 1 + Z.of_nat n)%Z -> (0 <= k)%Z -> (k + 1 < Z.of_nat (length ws))%Z -> (Z.of_nat (length ws) <= 128)%Z ->
  (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z -> limbs_ok ws ia (k + 1) ->
  (ia = 0%Z -> exists w0, nth_error ws 0 = Some w0 /\ (bv_unsigned w0 < 999999999)%Z) ->
  (forall w, nth_error ws (Z.to_nat ia) = Some w -> bv_unsigned w <> 0%Z) ->
  a1 = Z_to_bv 64 999999999 ->
  evt rsegs (fun ms' => exists (ia' k' : Z) a0' a2' m' ws',
      (0 <= ia' <= k')%Z /\ (k' <= k)%Z /\ (ia' <= ia)%Z /\ (ia - 1 <= ia')%Z /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia')) a0' a1 a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 (Z_to_bv 64 (B + 4 * k')) s8 s9 s10 s11 t3 t4 t5 t6) F
               (Z_to_bv 64 0xb10b8) fc None m' (seg_rom rsegs)
      /\ munch [(B, B + 4 * Z.of_nat (length ws))]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' B ws' /\ length ws' = length ws /\ limbs_ok ws' ia' (k + 2)
      /\ (forall i, (k + 2 <= i)%Z -> nth_error ws' (Z.to_nat i) = nth_error ws (Z.to_nat i))
      /\ (forall i, (0 <= i < ia')%Z -> nth_error ws' (Z.to_nat i) = nth_error ws (Z.to_nat i))
      /\ (forall w, nth_error ws' (Z.to_nat ia') = Some w -> bv_unsigned w <> 0%Z))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia)) (Z_to_bv 64 (B + 4 * k)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb1084) fc None m (seg_rom rsegs)).
Proof.
