(* [comment removed for export] *)
Lemma fmtD3a_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a3 a5 a6 a7 s7 s8 s9 t3 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz ir id i e p : Z) (ws : list word) (jA : list byte) (wd : word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (0 <= ia <= id)%Z -> (id < iz <= Z.of_nat (length ws))%Z -> (Z.of_nat (length ws) <= 128)%Z ->
  (0 <= ir <= 128)%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z -> limbs_ok ws ia iz ->
  nth_error ws (Z.to_nat id) = Some wd -> (i = 10 \/ i = 100 \/ i = 1000 \/ i = 10000 \/ i = 100000 \/ i = 1000000 \/ i = 10000000 \/ i = 100000000 \/ i = 1000000000)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -544) [C8 (Z_to_bv 64 0); CB 40 jA; C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); C8 (Z_to_bv 64 p)] ->
  (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z ->
  let v := bv_unsigned wd in let x := (v mod i)%Z in let P1 := ((x =? 0) && (id + 1 =? iz))%Z in
  evt rsegs (fun ms' => exists m' jA' s2' t4' s7',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia))
                    (Z_to_bv 64 (v / i * i)) a1 (Z_to_bv 64 (B + 4 * id)) a3 (Z_to_bv 64 (B + 4 * id + 65532)) a5 a6 a7
                    s2' (Z_to_bv 64 i) (Z_to_bv 64 103) (Z_to_bv 64 e) (Z_to_bv 64 (B + 4 * ir)) s7' wd (Z_to_bv 64 (v / i))
                    (Z_to_bv 64 (B + 4 * (id + 1))) (Z_to_bv 64 (B + 4 * iz)) t3 t4' t5 t6) F
               (Z_to_bv 64 (if P1 then 0xb10e4 else 0xb0cfc)) fc None m' (seg_rom rsegs)
      /\ (s2' = Z_to_bv 64 (if P1 then p else B + 4 * id + 65536)) /\ (s7' = Z_to_bv 64 (if P1 then B + 4 * id else x)) /\ (t4' = if P1 then Z_to_bv 64 103 else Z_to_bv 64 103)
      /\ munch [(bv_unsigned s0 + -544, bv_unsigned s0 + -472)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' B ws /\ length jA' = 32%nat
      /\ rw_cells rsegs m' (bv_unsigned s0 + -544) [C8 (Z_to_bv 64 0); CB 32 jA'; C8 (Z_to_bv 64 (B + 4 * id)); C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); C8 (Z_to_bv 64 p)])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia))
                    a0 a1 (Z_to_bv 64 (B + 4 * id)) a3 (Z_to_bv 64 (B + 4 * id + 65532)) a5 a6 a7
                    (Z_to_bv 64 (B + 4 * id + 65536)) (Z_to_bv 64 i) (Z_to_bv 64 103) (Z_to_bv 64 e) (Z_to_bv 64 (B + 4 * ir)) s7 s8 s9 (Z_to_bv 64 (-65532)) (Z_to_bv 64 (B + 4 * iz)) t3 (Z_to_bv 64 103) t5 t6) F
