  t3 = Z_to_bv 64 A1 -> s1 = Z_to_bv 64 A2 -> a2 = Z_to_bv 64 A3 -> s2 = Z_to_bv 64 A4 ->
  a7 = Z_to_bv 64 B1 -> s0 = Z_to_bv 64 B3 -> t1 = Z_to_bv 64 (A2 * 2 ^ 32) -> t4 = Z_to_bv 64 (A4 * 2 ^ 32) ->
