(* [comment removed for export] *)
Lemma limbsA_w ha la : 0 <= ha < 2 ^ 48 -> 0 <= la < 2 ^ 64 ->
  let A1 := Z.lor (Z.shiftr ha 32) 65536 in let A2 := Z.land ha 4294967295 in
  let A3 := Z.shiftr la 32 in let A4 := Z.land la 4294967295 in
  (0 <= A1 < 2 ^ 17 /\ 0 <= A2 < 2 ^ 32 /\ 0 <= A3 < 2 ^ 32 /\ 0 <= A4 < 2 ^ 32)
  /\ A1 * 2 ^ 96 + A2 * 2 ^ 64 + A3 * 2 ^ 32 + A4 = (ha + 2 ^ 48) * 2 ^ 64 + la
  /\ (Z.shiftl ha 32) mod 2 ^ 64 = (A2 * 2 ^ 32) mod 2 ^ 64
  /\ (Z.shiftl la 32) mod 2 ^ 64 = (A4 * 2 ^ 32) mod 2 ^ 64.
Proof.
