Lemma fpclassifyl_walk_inf : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (l h : Z),
  (0 <= l < 2 ^ 64)%Z -> (0 <= h < 2 ^ 64)%Z -> ((h mod 2 ^ 63) / 2 ^ 48 = 32767)%Z ->
  a0 = Z_to_bv 64 l -> a1 = Z_to_bv 64 h ->
  evt rsegs (fun ms' => exists c a1' a2' a3', (0 <= c <= 1)%Z /\
                ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 c) a1' a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                            F (ret_pc ra) fc None m (seg_rom rsegs))
