Definition frexpl_post (ra sp gp tp t1 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : word -> option byte) (pe : Z) (rlo rhi : Z) (ev : Z) : machine_state -> Prop :=
  fun ms' => exists t0' t2' a2' a3' a4' a5' a6' a7' m',
    ms' = MS (mkR ra sp gp tp t0' t1 t2' s0 s1 (Z_to_bv 64 rlo) (Z_to_bv 64 rhi) a2' a3' a4' a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(bv_unsigned sp + -32, bv_unsigned sp); (pe, pe + 4)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp) /\ rw_cells rsegs m' pe [C4 (Z_to_bv 64 ev)].

(* [comment removed for export] *)
Lemma frexpl_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo : Z) (N E pe : Z) (junk : word),
  stk rsegs m lo (bv_unsigned sp) -> mem_inv rsegs m -> (lo <= bv_unsigned sp - 32)%Z ->
  rw_cells rsegs m pe [C4 junk] -> (bv_unsigned sp <= pe)%Z ->
  qok N E -> bv_unsigned a0 = lo64 (qenc N E) -> bv_unsigned a1 = hi64 (qenc N E) -> a2 = Z_to_bv 64 pe ->
