(* [comment removed for export] *)
Lemma rndD_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s4 s8 s9 s10 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz id ir i u e : Z) (ws : list word) (jA1 jB : list byte) (wu c0 rlo c1 c2 c3 nsw pfx : word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (0 <= ia <= id)%Z -> (1 <= id)%Z -> (id < iz <= Z.of_nat (length ws))%Z -> (Z.of_nat (length ws) <= 128)%Z ->
  (0 <= ir <= 128)%Z -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z ->
  nth_error ws (Z.to_nat id) = Some wu -> bv_unsigned wu = u -> (0 <= u < 1000000000)%Z -> (10 <= i <= 1000000000)%Z ->
  limbs_ok ws ia id -> (ia = 0%Z -> exists w0, nth_error ws 0 = Some w0 /\ (bv_unsigned w0 < 999999999)%Z) ->
  (forall w, nth_error ws (Z.to_nat ia) = Some w -> bv_unsigned w <> 0%Z) ->
  rw_cells rsegs m (bv_unsigned s0 + -544) [C8 c0; CB 16 jA1; C8 (Z_to_bv 64 (B + 4 * id + 65532)); C8 rlo; C8 (Z_to_bv 64 (B + 4 * id)); C8 c1; C8 c2; C8 c3; CB 16 jB; C8 nsw; C8 pfx] ->
  evt rsegs (fun ms' => exists (ia' id' e' : Z) (ws' : list word) a0' a1' a2' a3' m',
      (ia - 1 <= ia' <= ia)%Z /\ (0 <= ia')%Z /\ (ia' <= id' <= id)%Z /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia'))
                    a0' a1' a2' a3' a4 a5 a6 a7
                    c3 (Z_to_bv 64 i) s4 (Z_to_bv 64 e') (Z_to_bv 64 (B + 4 * ir)) (Z_to_bv 64 (B + 4 * id')) s8 s9 s10
                    (Z_to_bv 64 (B + 4 * Z.min (id' + 1) iz)) t3 c2 t5 t6) F
               (Z_to_bv 64 0xb10f4) fc None m' (seg_rom rsegs)
      /\ munch [(B, B + 4 * Z.of_nat (length ws))]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' B ws' /\ length ws' = length ws /\ limbs_ok ws' ia' (id + 1)
      /\ (forall j, (id + 1 <= j)%Z -> nth_error ws' (Z.to_nat j) = nth_error ws (Z.to_nat j))
      /\ (forall j, (0 <= j < ia')%Z -> nth_error ws' (Z.to_nat j) = nth_error ws (Z.to_nat j))
      /\ (forall w, nth_error ws' (Z.to_nat ia') = Some w -> bv_unsigned w <> 0%Z)
      /\ ((a0 = Z_to_bv 64 0 /\ ia' = ia /\ id' = id /\ e' = e /\ ws' = ws)
          \/ (exists w', nth_error ws' (Z.to_nat ia') = Some w' /\ e' = (9 * (ir - ia') + ndigm1 (bv_unsigned w'))%Z)))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia))
                    a0 a1 a2 a3 a4 a5 a6 a7
                    (Z_to_bv 64 u) (Z_to_bv 64 i) s4 (Z_to_bv 64 e) (Z_to_bv 64 (B + 4 * ir)) (Z_to_bv 64 (B + 4 * id)) s8 s9 s10 (Z_to_bv 64 (B + 4 * iz)) t3 t4 t5 t6) F
