(* [comment removed for export] *)
Lemma pow10_cases m : (0 <= m <= 8)%Z ->
  (10 ^ (9 - m) = 10 \/ 10 ^ (9 - m) = 100 \/ 10 ^ (9 - m) = 1000 \/ 10 ^ (9 - m) = 10000 \/ 10 ^ (9 - m) = 100000 \/ 10 ^ (9 - m) = 1000000
