  rw_cells rsegs m (bv_unsigned s0 + -544) [C8 (Z_to_bv 64 0); CB 40 jA; C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); CB 8 jB;
                                           C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0xf8ac0); C8 (Z_to_bv 64 ns); C8 (Z_to_bv 64 pfx)] ->
  evt rsegs (fun ms' => exists (ia' iz' e' : Z) (ws' : list word) (w : word) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s3' s7' s8' s9' s10' t3' t5' t6'
