      /\ rw_cells rsegs m' (bv_unsigned s0 + -544) [C8 (Z_to_bv 64 0); CB 40 jA'; C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); CB 8 jB';
                                                  C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0xf8ac0); C8 nsw; C8 (Z_to_bv 64 pfx)])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (B + 4 * ia)) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 p) s3 (Z_to_bv 64 103) s5 (Z_to_bv 64 (B + 4 * ir)) s7 s8 s9 s10 (Z_to_bv 64 (B + 4 * iz)) t3 t4 t5 t6) F
